insert into affix_roots (root, en, sort) values
  ('ajar', 'teach', 1),
  ('makan', 'eat', 2),
  ('jalan', 'road · walk', 3),
  ('beli', 'buy', 4),
  ('tulis', 'write', 5)
insert into affix_forms (id, prefix, root, suffix, parts, meaning_en, rule_en) values
  (1, '', 'ajar', '', '[["ajar","root"]]'::jsonb, 'teach (root)', 'Rarely used alone. Add an affix to make a word.'),
  (2, 'ber', 'ajar', '', '[["bel","pre"],["ajar","root"]]'::jsonb, 'to study', 'ber- becomes bel- before “ajar”. It’s the one famous exception.'),
  (3, 'meN', 'ajar', '', '[["meng","pre"],["ajar","root"]]'::jsonb, 'to teach', 'meN- becomes meng- before a vowel.'),
  (4, 'meN', 'ajar', 'kan', '[["meng","pre"],["ajar","root"],["kan","suf"]]'::jsonb, 'to teach (a subject)', '-kan points at the thing being taught.'),
  (5, 'di', 'ajar', '', '[["di","pre"],["ajar","root"]]'::jsonb, 'is taught', 'di- makes it passive. It never changes the root.'),
  (6, 'di', 'ajar', 'kan', '[["di","pre"],["ajar","root"],["kan","suf"]]'::jsonb, 'is taught (a subject)', 'Passive of mengajarkan.'),
  (7, 'peN', 'ajar', '', '[["peng","pre"],["ajar","root"]]'::jsonb, 'instructor', 'peN- = the doer. Compare pelajar, “student”, built like belajar.'),
  (8, 'peN', 'ajar', 'an', '[["pel","pre"],["ajar","root"],["an","suf"]]'::jsonb, 'lesson', 'pe-…-an makes the result. Pengajaran is “the act of teaching”.'),
  (9, '', 'ajar', 'an', '[["ajar","root"],["an","suf"]]'::jsonb, 'teaching, doctrine', '-an turns the action into a thing.'),
  (10, '', 'makan', '', '[["makan","root"]]'::jsonb, 'to eat', 'Everyday verb, no affix needed.'),
  (11, 'meN', 'makan', '', '[["me","pre"],["makan","root"]]'::jsonb, 'to eat (something)', 'meN- becomes me- before m. Sounds formal.'),
  (12, 'di', 'makan', '', '[["di","pre"],["makan","root"]]'::jsonb, 'is eaten', 'di- passive.'),
  (13, 'ter', 'makan', '', '[["ter","pre"],["makan","root"]]'::jsonb, 'eaten by accident', 'ter- = it happened without meaning to.'),
  (14, 'peN', 'makan', '', '[["pe","pre"],["makan","root"]]'::jsonb, 'eater', 'pemakan sayur = vegetarian.'),
  (15, '', 'makan', 'an', '[["makan","root"],["an","suf"]]'::jsonb, 'food', '-an: the thing you eat.'),
  (16, 'peN', 'makan', 'an', '[["pe","pre"],["makan","root"],["an","suf"]]'::jsonb, 'nutrition, diet', 'pe-…-an: the whole system around eating.'),
  (17, '', 'jalan', '', '[["jalan","root"]]'::jsonb, 'road; to walk', 'Works alone in speech: “Jalan dulu!” (I’m off!).'),
  (18, 'ber', 'jalan', '', '[["ber","pre"],["jalan","root"]]'::jsonb, 'to walk', 'ber- = doing it, no object.'),
  (19, 'meN', 'jalan', 'kan', '[["men","pre"],["jalan","root"],["kan","suf"]]'::jsonb, 'to carry out, run', 'meN- becomes men- before j. -kan = make it go.'),
  (20, 'meN', 'jalan', 'i', '[["men","pre"],["jalan","root"],["i","suf"]]'::jsonb, 'to undergo', '-i points at where/what you go through: menjalani latihan.'),
  (21, 'di', 'jalan', 'kan', '[["di","pre"],["jalan","root"],["kan","suf"]]'::jsonb, 'is carried out', 'Passive of menjalankan.'),
  (22, 'peN', 'jalan', '', '[["pe","pre"],["jalan","root"]]'::jsonb, 'walker', 'pejalan kaki = pedestrian.'),
  (23, 'per', 'jalan', 'an', '[["per","pre"],["jalan","root"],["an","suf"]]'::jsonb, 'journey', 'per-…-an: the process. Selamat dalam perjalanan!'),
  (24, '', 'jalan', 'an', '[["jalan","root"],["an","suf"]]'::jsonb, 'the streets', 'makanan jalanan = street food.'),
  (25, '', 'beli', '', '[["beli","root"]]'::jsonb, 'buy (casual)', 'Fine in speech: “Nak beli apa?”'),
  (26, 'meN', 'beli', '', '[["mem","pre"],["beli","root"]]'::jsonb, 'to buy', 'meN- becomes mem- before b.'),
  (27, 'meN', 'beli', 'kan', '[["mem","pre"],["beli","root"],["kan","suf"]]'::jsonb, 'to buy for someone', '-kan = for the benefit of someone.'),
  (28, 'di', 'beli', '', '[["di","pre"],["beli","root"]]'::jsonb, 'is bought', 'di- passive.'),
  (29, 'ter', 'beli', '', '[["ter","pre"],["beli","root"]]'::jsonb, 'bought by mistake', 'ter- = unintended.'),
  (30, 'peN', 'beli', '', '[["pem","pre"],["beli","root"]]'::jsonb, 'buyer', 'peN- becomes pem- before b, same as meN-.'),
  (31, 'peN', 'beli', 'an', '[["pem","pre"],["beli","root"],["an","suf"]]'::jsonb, 'a purchase', 'pe-…-an: the act or result.'),
  (32, '', 'beli', 'an', '[["beli","root"],["an","suf"]]'::jsonb, 'item bought', 'Less common than pembelian.'),
  (33, '', 'tulis', '', '[["tulis","root"]]'::jsonb, 'write (root)', 'Usually takes an affix.'),
  (34, 'meN', 'tulis', '', '[["me","pre"],["nulis","root"]]'::jsonb, 'to write', 'meN- + t → men-, and the t drops: menulis.'),
  (35, 'meN', 'tulis', 'kan', '[["me","pre"],["nulis","root"],["kan","suf"]]'::jsonb, 'to write down', 'Same t-drop, plus -kan for the thing written.'),
  (36, 'di', 'tulis', '', '[["di","pre"],["tulis","root"]]'::jsonb, 'is written', 'di- keeps the t.'),
  (37, 'ter', 'tulis', '', '[["ter","pre"],["tulis","root"]]'::jsonb, 'in writing', 'ujian bertulis = written exam. tertulis = stated in writing.'),
  (38, 'peN', 'tulis', '', '[["pe","pre"],["nulis","root"]]'::jsonb, 'writer', 'The t drops here too.'),
  (39, 'peN', 'tulis', 'an', '[["pe","pre"],["nulis","root"],["an","suf"]]'::jsonb, 'the writing process', 'pe-…-an.'),
  (40, '', 'tulis', 'an', '[["tulis","root"],["an","suf"]]'::jsonb, 'writing, script', 'tulisan Jawi = Jawi script.')
insert into roleplay_turns (id, unit_id, sort, speaker, line_ms, line_en) values
  (1, 3, 1, 'Pelayan · waiter', 'Nak makan apa, bang?', 'What would you like, bro?'),
  (2, 3, 2, 'Pelayan · waiter', 'Minum?', 'Something to drink?'),
  (3, 3, 3, 'Pelayan · waiter', 'Makan sini ke bungkus?', 'Eat here or take away?'),
