insert into roleplay_replies (id, turn_id, text_ms, is_correct, feedback_en) values
  (1, 1, 'Nasi lemak satu.', true, 'Perfect. Item + number is all you need.'),
  (2, 1, 'Saya nasi lemak.', false, '“I am nasi lemak”. Funny, but drop the saya.'),
  (3, 1, 'Berapa nasi lemak?', false, 'That asks how much it costs. Order first.'),
  (4, 2, 'Teh tarik kurang manis.', true, 'kurang manis = less sweet. Very Malaysian.'),
  (5, 2, 'Minum teh tarik saya.', false, 'Word order is off. Just name the drink.'),
  (6, 2, 'Tidak minum manis.', false, 'Understandable, but “kurang manis” is how people say it.'),
  (7, 3, 'Bungkus.', true, 'One word does it.'),
  (8, 3, 'Makan bungkus.', false, '“Eat take-away” mixes both answers.'),
  (9, 3, 'Sini bungkus.', false, 'Pick one: sini or bungkus.'),
  (10, 4, 'Terima kasih, bang!', true, 'Bagus! Order complete.'),
  (11, 4, 'Sama-sama.', false, 'That’s “you’re welcome”. He hasn’t thanked you yet.'),
  (12, 4, 'Tidak apa.', false, 'That means “never mind”. Pay and say thanks.')
